-- Swamp of Sorrows: spawns, objects and drops of the Cataclysm quests. Based on Legends of Azeroth 5.4.8, checked
-- against the spawn maps on Wowhead MoP Classic.
--
-- The Stonard and Marshtide invasion quests (27795, 27843, 27849, 27855, 27857) ask for Stonard Ogres, Stonard
-- Warlocks and Defenders and Marshtide Mages and Invaders, none of which was spawned. "In With a Bang" (27600) needs
-- three objects that had a loot table and no spawn, "Cutting Supply" (27851) the Stonard Supplies and "Drinks on the
-- Rocks" (27592) the Stolen Silversnap Ice from the Silt Crawlers.

DELETE FROM `creature` WHERE `guid` BETWEEN 8316700 AND 8316820;

DELETE FROM `gameobject` WHERE `guid` BETWEEN 1068214 AND 1068234;

DELETE FROM `creature_loot_template` WHERE `entry`=922 AND `item`=61356;

-- Combat spells of the invasion creatures.
UPDATE `creature_template` SET `AIName`='SmartAI' WHERE `entry` IN (46765, 46770, 46775, 46869, 46870);
DELETE FROM `smart_scripts` WHERE `entryorguid` IN (46765, 46770, 46775, 46869, 46870) AND `source_type`=0;
